def fill_matrix(n, k):
    if k > n * n // 2:
        return -1

    matrix = [[0] * n for _ in range(n)]
    max_ones = n * n
    max_lexicographical = -1

    for i in range(1 << max_ones):
        if bin(i).count('1') == k:
            current_matrix = [[0] * n for _ in range(n)]
            ones_placed = 0
            for row in range(n):
                for col in range(row, n):
                    if i & (1 << ones_placed):
                        current_matrix[row][col] = 1
                        current_matrix[col][row] = 1
                    ones_placed += 1

            if all(current_matrix[i][j] == current_matrix[j][i] for i in range(n) for j in range(n)):
                current_lexicographical = ''.join(''.join(str(x) for x in row) for row in current_matrix)
                if current_lexicographical > str(max_lexicographical):
                    max_lexicographical = current_lexicographical
                    matrix = current_matrix

    if matrix == [[0] * n for _ in range(n)]:
        return -1

    return '\n'.join(' '.join(str(x) for x in row) for row in matrix)

